/**
 * reworkLoopGuard.js — the rework no-op loop guard (gh-957), pure side.
 *
 * Live pathology (dart PR #424, 2026-10-17 08:00–10:55Z): the SM armed
 * agent:rework on unresolved review threads 7 times in 2 hours; every leg
 * closed itself 'successful' with ZERO pushed commits and ZERO resolved
 * threads on the same head; the arm rule re-matched on the next tick every
 * time and the loop starved the whole machine queue (7 other PRs got
 * nothing). The existing empty-lap cap (review #703) only covers the
 * red-gate arm via fail_validation's 🔴 markers — the threads-armed path
 * had NO bound.
 *
 * This module is the pure side of the bound:
 *
 *   Lap markers   — the rework post-action (js/pushReworkChanges.js) stamps
 *                   ONE machine-parseable marker per leg close recording
 *                   {head, pushed: 0|1, resolved: N, at}. Trusted only from
 *                   machine identities (the same allowlist doctrine as
 *                   reviewVerdicts.js / reworkConsumption.js — the marker
 *                   format is public).
 *   The decision  — consecutiveNoopLaps(): the newest-first run of laps on
 *                   the SAME head with pushed === 0 AND resolved === 0. A
 *                   progress lap (pushed or resolved) or a different head
 *                   ends the run — so a human push (new head) or a leg that
 *                   actually resolves threads resets the budget by
 *                   construction. At >= maxNoopLaps the SM arm actions
 *                   (arm_rework + restore_rework_arm) WITHHOLD the arm and
 *                   escalate the owner ONCE per head (escalation marker
 *                   dedup): a label (ESCALATION_LABEL) + a 🛑 PR comment.
 *
 * Pure module — no dmtools globals; smAgent feeds it comment payloads and
 * applies the decisions; pushReworkChanges builds the lap markers.
 * GraalJS-clean (var + plain functions, JSON-safe data only).
 */
'use strict';

// gh-957: consecutive no-op rework laps on one head before the arm is
// withheld. Deployment-tunable via jobParams.noopLapMax (same shape as
// redHeadCap / emptyLapMax).
var DEFAULT_NOOP_LAP_MAX = 2;

// One hidden marker per leg close + one visible audit line.
var LAP_MARKER_PREFIX = '<!-- dmtools:rework-lap ';
// One hidden marker per escalation (the once-per-head dedup the arm
// actions consult before re-posting).
var ESCALATION_MARKER_PREFIX = '<!-- dmtools:rework-loop-escalated ';
var MARKER_SUFFIX = ' -->';

// The escalation carrier on the PR: the machine stops re-arming while this
// label stands; a human push (new head) resets the lap budget, and clearing
// the label is a human decision.
var ESCALATION_LABEL = 'rework-loop-escalated';

/**
 * Builds the per-leg-close audit marker comment. pushed: 0|1 (a real
 * production change landed), resolved: count of threads the leg resolved.
 * runUrl: the rework run URL for the audit trail (null on local runs).
 * Returns null on an unbuildable record — callers skip the post.
 */
function buildLapMarker(headSha, pushed, resolved, runUrl, atIso) {
    if (!headSha || typeof headSha !== 'string') return null;
    var payload = {
        head: headSha,
        pushed: pushed ? 1 : 0,
        resolved: (typeof resolved === 'number' && resolved > 0) ? Math.floor(resolved) : 0,
        at: atIso || new Date().toISOString()
    };
    if (runUrl) payload.run = String(runUrl);
    return LAP_MARKER_PREFIX + JSON.stringify(payload) + MARKER_SUFFIX + '\n' +
        '📓 rework lap on head ' + String(headSha).substring(0, 7) + ': pushed ' +
        payload.pushed + ', resolved ' + payload.resolved + ' (gh-957 loop-guard audit).';
}

/**
 * Builds the once-per-head escalation comment (🛑 + hidden marker). Posted
 * by the SM arm actions when the no-op lap budget is exhausted.
 */
function buildEscalationComment(headSha, laps, maxLaps, atIso) {
    if (!headSha || typeof headSha !== 'string') return null;
    var payload = { head: headSha, laps: laps, at: atIso || new Date().toISOString() };
    return ESCALATION_MARKER_PREFIX + JSON.stringify(payload) + MARKER_SUFFIX + '\n' +
        '🛑 rework no-op loop guard (gh-957) — ' + laps + '/' + maxLaps +
        ' consecutive rework leg(s) on head ' + headSha + ' closed with ZERO pushed commits and ZERO resolved threads. ' +
        'The machine stops re-arming agent:rework here (label `' + ESCALATION_LABEL + '`) — a human owns this PR: ' +
        'push a fix (a NEW head resets the budget) or resolve/dismiss the open review threads. ' +
        'The threads census and the leg input are now the same source (GraphQL reviewThreads), so a leg that ' +
        'determines every thread is addressed/invalid can resolve them with an audit reply — that path also ' +
        'resets this budget.';
}

function commentAuthorLogin(item) {
    if (!item) return null;
    var u = item.user || item.author;
    if (!u) return null;
    var login = u.login || u.name;
    return login ? String(login).toLowerCase() : null;
}

function parseMarkers(comments, prefix, opts) {
    var list = Array.isArray(comments) ? comments : [];
    var allow = (opts && Array.isArray(opts.authorLogins) && opts.authorLogins.length)
        ? opts.authorLogins : null;
    var out = [];
    for (var i = 0; i < list.length; i++) {
        if (allow) {
            var who = commentAuthorLogin(list[i]);
            var trusted = false;
            for (var a = 0; a < allow.length; a++) {
                if (who && who === String(allow[a] || '').toLowerCase()) { trusted = true; break; }
            }
            if (!trusted) continue;
        }
        var text = String((list[i] && list[i].body) || '');
        var start = text.indexOf(prefix);
        if (start === -1) continue;
        start += prefix.length;
        var end = text.indexOf(MARKER_SUFFIX, start);
        if (end === -1) continue;
        var parsed;
        try { parsed = JSON.parse(text.substring(start, end).trim()); } catch (e) { continue; }
        if (!parsed || typeof parsed !== 'object') continue;
        parsed.atMs = Date.parse(parsed.at || '');
        parsed.order = i;
        out.push(parsed);
    }
    // Timestamp order, payload order as tiebreak (reworkConsumption parity).
    out.sort(function(a, b) {
        var aTime = isNaN(a.atMs) ? -1 : a.atMs;
        var bTime = isNaN(b.atMs) ? -1 : b.atMs;
        if (aTime !== bTime) return aTime < bTime ? -1 : 1;
        return (a.order || 0) - (b.order || 0);
    });
    return out;
}

function parseLapMarkers(comments, opts) {
    return parseMarkers(comments, LAP_MARKER_PREFIX, opts);
}

function parseEscalationMarkers(comments, opts) {
    return parseMarkers(comments, ESCALATION_MARKER_PREFIX, opts);
}

function isNoopLap(m) {
    return !!m && m.pushed === 0 && (typeof m.resolved !== 'number' || m.resolved === 0);
}

/**
 * The newest-first run of no-op laps on ONE head: walks the (time-sorted)
 * lap markers backward from the newest, counting while the lap is a no-op
 * (pushed === 0 && resolved === 0) on the requested head. Stops at the
 * first progress lap or a different head — so one resolving/pushing leg or
 * a head move resets the budget. Markers for other heads are skipped, not
 * terminating — a quiet interleave must not mask the run on THIS head.
 */
function consecutiveNoopLaps(markers, headSha) {
    if (!headSha) return 0;
    var list = (markers || []).filter(function(m) {
        return !!m && m.head === headSha;
    });
    var run = 0;
    for (var i = list.length - 1; i >= 0; i--) {
        if (!isNoopLap(list[i])) break;
        run++;
    }
    return run;
}

/**
 * True when an escalation was already posted for this head (the once-per-head
 * dedup the withholding branches consult before re-posting).
 */
function hasEscalationForHead(escalationMarkers, headSha) {
    if (!headSha) return false;
    return (escalationMarkers || []).some(function(m) {
        return !!m && m.head === headSha;
    });
}

/**
 * The arm-side decision (pure). state:
 *   markers          — time-sorted lap markers (parseLapMarkers output)
 *   escalationMarkers— parsed escalation markers (same comments, dedup)
 *   headSha         …

/**
 * reviewThreadInventory.js — the review-thread inventory for rework/review
 * leg input prep (gh-957).
 *
 * Live pathology (dart PR #424 / gh-957, 2026-10-17 08:00–10:55Z): the SM's
 * arm rule counts unresolved threads via GraphQL reviewThreads
 * (github_get_pr_review_threads — isResolved === false) and counted 64.
 * The rework leg's input was built from github_get_pr_conversations, which
 * surfaced only 2 threads (both machine notices) — the leg concluded
 * 'Review decision is NONE, nothing to fix', resolved nothing, and the
 * unresolved-threads armer re-armed rework 7 times in 2 hours, starving the
 * whole machine queue. The two sides of the arm condition NEVER agreed.
 *
 * This module is the single inventory builder both collection paths
 * (js/common/scm.js fetchDiscussions and js/common/githubHelpers.js
 * fetchDiscussionsAndRawData) delegate to:
 *
 *   GraphQL-first — when the reviewThreads fetch succeeds with at least one
 *   node, the inventory is ENUMERATED from the GraphQL nodes (the exact same
 *   census the SM arm rule counts), enriched per-thread from the matching
 *   conversation (body/author/path/line/replies the GraphQL payload may not
 *   carry). Threads the conversations export missed entirely (the dart #424
 *   shape) still land in the inventory with their resolve id (threadId) and
 *   reply anchor (rootCommentId).
 *
 *   Legacy fallback — when the GraphQL fetch fails or returns zero nodes,
 *   the inventory is built from conversations exactly as before (REST
 *   resolved/isResolved flags enriched with GraphQL ids when available).
 *
 * The gh-808 machine-notice doctrine is preserved on BOTH paths: notice
 * threads never appear in rawThreads or the markdown (AC1); conversation-only
 * notices are still counted for the exclusion summary note.
 *
 * Pure module — no dmtools globals; the callers fetch conversations and the
 * GraphQL payload and pass them in. GraalJS-clean (var + plain functions,
 * JSON-safe data only).
 */
'use strict';

var machineNotice = require('./machineNotice.js');

/**
 * Normalize the github_get_pr_review_threads return (JSON string | node
 * array | full envelope | {nodes:[...]} short envelope) into a node array.
 */
function parseGraphQLNodes(raw) {
    if (!raw) return [];
    var data = raw;
    if (typeof data === 'string') {
        try { data = JSON.parse(data); } catch (e) { return []; }
    }
    if (Array.isArray(data)) return data;
    var rt = data && data.data && data.data.repository &&
             data.data.repository.pullRequest &&
             data.data.repository.pullRequest.reviewThreads;
    if (rt && Array.isArray(rt.nodes)) return rt.nodes;
    if (data && Array.isArray(data.nodes)) return data.nodes;
    return [];
}

/**
 * REST conversation root comment id (id || databaseId) — the join key
 * between the conversations export and the GraphQL first-comment databaseId.
 */
function conversationRootId(thread) {
    var root = (thread && (thread.rootComment || thread)) || {};
    return root.id || root.databaseId || null;
}

function indexConversations(conversations) {
    var byId = {};
    (conversations || []).forEach(function(c) {
        var id = conversationRootId(c);
        if (id !== null && id !== undefined) byId[String(id)] = c;
    });
    return byId;
}

/**
 * Map one GraphQL reviewThread node to the enriched internal thread shape
 * ({rootCommentId, threadId, path, line, resolved, bot, body, author, date,
 * replies}), filling body/author/path/line/replies from the matched
 * conversation when the node's first comment does not carry them (the
 * dmtools export may omit fields). The RESOLVED flag is GraphQL truth only —
 * the arm rule counts isResolved, so the inventory must never disagree.
 */
function threadFromGraphQLNode(node, conversation) {
    var first = (node.comments && node.comments.nodes && node.comments.nodes[0]) || {};
    var convRoot = conversation ? (conversation.rootComment || conversation) : {};
    var author = (first.author && (first.author.login || first.author.name)) || '';
    if (!author) {
        author = convRoot.user ? (convRoot.user.login || '') :
            (convRoot.author ? (convRoot.author.login || convRoot.author.name || '') : '');
    }
    var body = String(first.body || convRoot.body || '').trim();
    var path = node.path || (conversation && conversation.path) || null;
    var line = (node.line === 0 || node.line) ? node.line
        : (conversation ? (conversation.line || conversation.original_line || null) : null);
    return {
        rootCommentId: first.databaseId || null,
        threadId: node.id || null,
        path: path,
        line: line,
        resolved: node.isResolved === true,
        bot: machineNotice.isBotAuthor(author),
        body: body,
        author: author || 'unknown',
        date: convRoot.created_at ? String(convRoot.created_at).substring(0, 10) : '',
        replies: (conversation && Array.isArray(conversation.replies)) ? conversation.replies : []
    };
}

/**
 * GraphQL-first inventory (gh-957): enumerate the SAME census the SM arm
 * rule counts. Notice threads (enriched body matches a harness marker) are
 * dropped and counted. Conversation-only notices — the gh-808 corpus shape —
 * are counted for the exclusion note but never enumerated (they are not
 * GraphQL review threads; the arm rule does not count them either).
 */
function buildFromGraphQL(nodes, conversations) {
    var convById = indexConversations(conversations);
    var enriched = [];
    var noticeCount = 0;
    var matchedConvIds = {};
    nodes.forEach(function(node) {
        if (!node) return;
        var first = (node.comments && node.comments.nodes && node.comments.nodes[0]) || {};
        var conv = null;
        if (first.databaseId !== null && first.databaseId !== undefined) {
            conv = convById[String(first.databaseId)] || null;
            if (conv) matchedConvIds[String(first.databaseId)] = true;
        }
        var t = threadFromGraphQLNode(node, conv);
        if (machineNotice.isMachineNoticeBody(t.body)) {
            noticeCount++;
            return;
        }
        enriched.push(t);
    });
    (conversations || []).forEach(function(c) {
        var id = conversationRootId(c);
        if (id !== null && id !== undefined && matchedConvIds[String(id)]) return;
        var root = c.rootComment || c;
        if (machineNotice.isMachineNoticeBody(String(root.body || '').trim())) noticeCount++;
    });
    var unresolved = 0;
    nodes.forEach(function(n) { if (n && n.isResolved !== true) unresolved++; });
    return {
        enriched: enriched,
        noticeCount: noticeCount,
        source: 'graphql',
        graphqlTotal: nodes.length,
        graphqlUnresolved: unresolved
    };
}

