var LAP_MARKER_PREFIX = '<!-- dmtools:rework-lap ';
// One hidden marker per escalation (the once-per-head dedup the arm
// actions consult before re-posting).
var ESCALATION_MARKER_PREFIX = '<!-- dmtools:rework-loop-escalated ';
var MARKER_SUFFIX = ' -->';

