// head move resets it by construction (markers are head-keyed).
// A read failure fails OPEN (empty history → arm): a broken
// comment read must not strand a red head this gate exists to
// un-stall.
var redGated = rule.redHeadGated === true;
var redGateHead = redGated
    ? ((ticket.pr && ticket.pr.headSha) || ticket.headSha) : null;
var redGateMarks = redGated
    ? failMarkerState(effectiveRepoInfo, ticket.prNumber) : null;
var redGatePrior = (redGated && redGateHead)
    ? (redGateMarks.redHeads[redGateHead] || 0) : 0;
var redGateCap = redHeadCapOf(RUN_JOB_PARAMS);
var redGateLine = (redGated && redGateHead)
    ? redHeadMarkerLine(redGatePrior, redGateHead, redGateCap) : null;
try {
    if (DRY) {
        console.log('  🧪 [dry] ' + key + ' would arm agent:rework (' +
            (redGated ? 'red pre-merge gate, first validation included — gh-917' :
             'unresolved review threads') + ' on PR #' + ticket.prNumber + ')');
        processedKeys.push(key);
        continue;
    }
    if (redGated && redGatePrior >= redGateCap) {
        // Cap reached: withhold + escalate ONCE per head. The
        // 🛑 marker in the escalation comment is the dedup —
        // failMarkerState parsed it from the same fetch; a read
        // failure above leaves reworkWithheld empty (re-post,
        // fail toward visibility). Repeat ticks stay quiet (no
        // processedKeys — suppressed decisions don't pollute
        // the tick summary, same shape as the latch consult).
        if (redGateMarks.reworkWithheld[redGateHead]) {
            console.log('  ⏭️  ' + key + ' rework arm stays withheld at cap (' +
                redGatePrior + '/' + redGateCap + ' reds on head ' +
                String(redGateHead).substring(0, 7) + ') — escalation already posted (gh-917)');
            continue;
        }
        githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).postComment(ticket.prNumber,
            '\uD83D\uDED1 rework arm withheld on head ' + redGateHead + ' — ' +
            redGatePrior + '/' + redGateCap + ' red arming attempts left the head unchanged' +
            ' (gh-917). The rework leg keeps closing without a fix (a violation class the agent' +
            ' cannot repair without the local toolchain) — the machine stops retrying here.' +
            ' A human owns this PR: push a fix (a NEW head restarts the budget and validation)' +
            ' or resolve the violation at its source.');
        console.log('  🛑 ' + key + ' rework arm WITHHELD at cap (' + redGatePrior + '/' +
            redGateCap + ' reds on head ' + String(redGateHead).substring(0, 7) +
            ') — owner escalated (gh-917: no infinite retry)');
        processedKeys.push(key);
        continue;
    }
    // gh-807 arming-side sticky approval (AC3): the effective
    // verdict for the CURRENT head must not be APPROVE — unless
    // BLOCKING threads remain in the record's census. Same rule
    // the rework side enforces (prHasApproved, owner rule
    // 2026-09-21) finally bound onto the ARMING side: an APPROVE
    // verdict with only suggestion-tier threads keeps the
    // approval and does NOT arm rework (that was the #1428
    // coexistence). Fail-open: no records / broken read → arm
    // as before (pre-gh-807 PRs).
    var armGate = reworkArmGate(effectiveRepoInfo, ticket,
        verdictMachineLogins(effectiveConfig));
    if (!armGate.arm) {
        console.log('  ⏭️  ' + key + ' rework arm withheld — APPROVE verdict on head ' +
            armGate.headShort + ' is authoritative (gh-807: suggestions do not trigger rework)');
        processedKeys.push(key);
        continue;
    }
    if (armGate.effective && armGate.effective.record) {
        console.log('  ℹ️  ' + key + ' rework arm allowed — ' + armGate.reason +
            ' on head ' + armGate.headShort);
    }
    // gh-957 no-op loop guard: count the consecutive rework laps
    // on THIS head that closed with zero pushed commits AND zero
    // resolved threads (live dart #424: 7 legs / 2h, every leg
    // 'successful', the arm re-matched every tick and starved
    // the whole queue). At the cap the arm is WITHHELD and the
    // owner is escalated once per head (label + 🛑 comment) —
    // instead of burning the machine forever. The lap markers
    // are stamped by pushReworkChanges and machine-author-gated
    // (the marker format is public). A lap that pushed or
    // resolved anything, or a new head, resets the count.
    var noopHead = redGateHead ||
        ((ticket.pr && ticket.pr.headSha) || ticket.headSha) || null;
    // gh-957: the machineAuthor doctrine — no configured machine
    // identity means no trusted markers at all; the guard stays
    // inert (arm as before) rather than trusting everyone.
    var noopLogins = verdictMachineLogins(effectiveConfig);
    if (noopHead && noopLogins.length) {
        var noopComments = prCommentList(effectiveRepoInfo, ticket.prNumber);
        var noopAllow = { authorLogins: noopLogins };
        var noopDecision = reworkLoopGuardModule.shouldWithholdArm({
            markers: reworkLoopGuardModule.parseLapMarkers(noopComments, noopAllow),
            escalationMarkers: reworkLoopGuardModule.parseEscalationMarkers(noopComments, noopAllow),
            headSha: noopHead,
            maxNoopLaps: noopLapMaxOf(RUN_JOB_PARAMS)
        });
        if (noopDecision.withhold) {
            if (noopDecision.escalate) {
                try {
                    githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo)
                        .addLabel(ticket.prNumber, reworkLoopGuardModule.ESCALATION_LABEL);
                } catch (eLabel) {
                    console.warn('  ⚠️ ' + key + ' loop-guard escalation label failed: ' + (eLabel.message || eLabel));
                }
                try {
                    githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).postComment(
                        ticket.prNumber,
                        reworkLoopGuardModule.buildEscalationComment(
                            noopHead, noopDecision.laps, noopDecision.maxLaps));
                } catch (eComment) {
                    console.warn('  ⚠️ ' + key + ' loop-guard escalation comment failed: ' + (eComment.message || eComment));
                }
                console.log('  🛑 ' + key + ' agent:rework WITHHELD — rework no-op loop guard (' +
                    noopDecision.laps + '/' + noopDecision.maxLaps + ' empty laps on head ' +
                    String(noopHead).substring(0, 7) + ', gh-957) — owner escalated (label +' +
                    ' comment); a new head or a resolving leg resets the budget');
                processedKeys.push(key);
            } else {
                console.log('  ⏭️  ' + key + ' agent:rework stays withheld — no-op loop guard' +
                    ' escalation already posted for head ' + String(noopHead).substring(0, 7) + ' (gh-957)');
            }
            continue;
        }
    }
    githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).addLabel(ticket.prNumber, 'agent:rework');
    if (redGated) {
        // gh-917 red-gate arm: the comment LEADS with the shared
        // red-head marker line (the budget the next arm and the
        // validate-armed redHeadSkip both read), then the reason.
        githubTracker(effectiveRepoInfo.owner, effectiveRepoInfo.repo).postComment(ticket.prNumber,
            (redGateLine ? redGateLine + '\n' : '') +
            '\uD83D\uDD34 Red pre-merge gate on the head with no armed validation — rework armed' +
            ' (gh-917: first validation included, review or no review). The rework runner pushes a' +
            ' fix and validation re-runs on the new head (validate-fresh). After ' + redGateCap +
            ' red arming attempts on the SAME head the arm is withheld and a human is escalated' +
            ' (no infinite retry).');
