        var repo = java.lang.System.getenv('GITHUB_REPOSITORY');
        var runId = java.lang.System.getenv('GITHUB_RUN_ID');
        if (server && repo && runId) {
            return String(server) + '/' + String(repo) + '/actions/runs/' + String(runId);
